// Regression test for the calc-element matrix-size integer overflow fixed for
// #1447 (Solve) and #1448 (Transpose) in IccProfLib/IccMpeCalc.cpp.
//
// CIccOpDefTranspose::Exec / CIccOpDefSolve::Exec computed the matrix element
// count as `int nSize = r*c`, with r,c = (icUInt16Number select field)+1, each
// up to 65536.  r*c reaches ~2^32 and overflowed int (UBSan: "65536 * 32768
// cannot be represented in type 'int'" at IccMpeCalc.cpp:584 / :622), wrapping
// negative and slipping past the `nSize>ss` guard into a bad resize / OOB stack
// index.  The fix computes the products in size_t so the guard rejects them.
//
// The two embedded profiles are the minimized PoCs from the verified external
// reports by @h0rk1p (bisected to 1f0a9dd, 2015):
//   tran-v1ffff-v2-7fff.icc  -> Transpose, select v1=0xffff v2=0x7fff  (#1448)
//   solv-v1ffff-v2-7fff.icc  -> Solve,     select v1=0xffff v2=0x7fff  (#1447)
// (source: github.com/xsscx/fuzz graphics/icc; 1776 bytes each).  Each drives a
// CMM transform exactly as `iccRoundTrip <file>` does, reaching the op's Exec.
//
// This test must be built/run under the signed-integer-overflow sanitizer (the
// CI ASAN+UBSAN tool job): pre-fix the multiply traps and aborts the process;
// post-fix it completes.  Validation already caps ArgsUsed at icMaxDataStackSize,
// so Begin() succeeds and Apply() really executes the op -- asserting Begin==Ok
// guarantees the overflow path is exercised (not skipped by an early rejection).
//
// Exit code 0 = pass, 1 = the guarded regression reappeared.

#include "IccProfile.h"
#include "IccCmm.h"
#include "IccDefs.h"

#include <cstdio>
#include <vector>

static int g_failures = 0;
static void check(bool cond, const char *msg) {
  if (cond) { std::printf("ok:   %s\n", msg); }
  else      { std::printf("FAIL: %s\n", msg); ++g_failures; }
}

