// Run a profile (in memory) through a CMM the way iccRoundTrip does, exercising
// the calc element's Transpose/Solve op.  Survives = no overflow trap.
static void exercise(const char *label, const unsigned char *bytes, unsigned len) {
  std::printf("\n[ %s ]\n", label);
  // AddXform copies/opens from memory; keep a mutable buffer for its lifetime.
  std::vector<icUInt8Number> buf(bytes, bytes + len);

  CIccCmm cmm(icSigUnknownData, icSigUnknownData, true);
  icStatusCMM aStat = cmm.AddXform(buf.data(), static_cast<icUInt32Number>(buf.size()),
                                   icPerceptual);
  check(aStat == icCmmStatOk, "AddXform built (calc A2B profile parsed)");
  if (aStat != icCmmStatOk) return;

  icStatusCMM bStat = cmm.Begin();
  // Begin validates the op sequence; with ArgsUsed capped it succeeds, so the
  // subsequent Apply genuinely runs the overflowing Transpose/Solve op.
  check(bStat == icCmmStatOk, "Begin validated the calc sequence (op is live in Apply)");
  if (bStat != icCmmStatOk) return;

  icFloatNumber in[16] = {0.5f, 0.5f, 0.5f};
  icFloatNumber out[16] = {0};
  cmm.Apply(out, in);   // pre-fix: signed-overflow trap here aborts the process
  check(true, "Apply ran the matrix op without an integer-overflow trap");
}

int main() {
  exercise("Transpose tran(65536,32768) -- #1448", kTranPoc, (unsigned)sizeof(kTranPoc));
  exercise("Solve solv(65536,32768) -- #1447",     kSolvPoc, (unsigned)sizeof(kSolvPoc));

  if (g_failures) { std::printf("\n%d check(s) FAILED\n", g_failures); return 1; }
  std::printf("\nall checks passed\n");
  return 0;
}
